#include "common_alt.h"
int main(){ double fs=48000; struct C{const char*n;BandParams b;}; std::vector<C> cs={{"Bell 40 +12 Q4",band(Bell,40,12,4)},{"Bell 100 -18 Q20",band(Bell,100,-18,20)},{"LowCut 30 48",band(LowCut,30,0,1,48)},{"Notch 60 Q10",band(Notch,60,0,10)},{"HighCut 18k 96",band(HighCut,18000,0,1,96)}};
 for(auto&c:cs){ Engine e; e.prepare(fs,512); e.configurePhase(1,1); Engine::Global g; e.setGlobal(g); e.setBand(0,c.b); int lat=e.latencySamples(), n=lat*2+9000; std::vector<float> l(n,0),r(n,0); l[0]=r[0]=1; for(int i=0;i<n;i+=512) e.process(l.data()+i,r.data()+i,nullptr,nullptr,std::min(512,n-i)); std::vector<double> h(l.begin(),l.end());
  double emax=0, deep=0; for(int k=0;k<400;++k){ double f=20*std::pow(1000.0,k/399.0); double a=anaDb(c.b,f), d=20*std::log10(std::abs(dft(h,f,fs))+1e-30); if(a>-40) emax=std::max(emax,std::abs(d-a)); else deep=std::max(deep,d-a);} std::printf("  %-18s err>-40dB %.3f  worst excess below -40 dB %+.1f\n",c.n,emax,deep);} }
